    const pot = (n) => 2 ** Math.ceil(Math.log2(n)), c = document.createElement('canvas'); c.width = pot(im.naturalWidth); c.height = pot(im.naturalHeight);
    c.getContext('2d').drawImage(im, 0, 0, c.width, c.height);
