    const comp = ac.createDynamicsCompressor(); comp.threshold.value = -12; comp.knee.value = 12; comp.ratio.value = 3; comp.attack.value = 0.002; comp.release.value = 0.12;
    bus.connect(comp); comp.connect(ac.destination);
